        height: 14px;
        width: 14px;
        fill: #0d5c91
    }

    .q10805 .tool-tip .popup {
        visibility: hidden;
        opacity: 0;
        position: absolute;
        text-align: left;
        transform: translateX(-50%);
        transition: opacity .1s;
        top: -9999px;
        left: -9999px;
        z-index: 9999;
        height: 0;
        width: max-content
    }

