    /* Toggle button (only appears when height is small) */
    .ui-toggle {
        position: fixed;
        z-index: 10000;
        background: #222;
        color: white!important;
        border-radius: 50%;
        width: 25px;
        height: 25px;
        /* default hidden state for keyboard-first reveal handled per-button */
        display: none;
    }

    /* top/bottom specific positions */
    .ui-toggle-top { top: 0.5rem; left: 0.5rem; }
    .ui-toggle-bottom { bottom: 0.5rem; left: 0.5rem; }

    /* === Height-based compact mode trigger === */
    @media (max-height: 480px) {
        .ui-toggle {
            display: block;
        }

        body.ui-terminal-pc .ui-toggle-top {
            opacity: 1;
            pointer-events: auto;
            transform: translateY(0);
        }

        body.ui-terminal-pc .ui-toggle-bottom {
            opacity: 0;
            pointer-events: none;
            transform: translateY(6px);
            transition: opacity .12s ease, transform .12s ease;
        }
        body.ui-terminal-pc .ui-toggle-bottom:focus {
            opacity: 1;
            pointer-events: auto;
            transform: translateY(0);
        }

        body.ui-terminal-nonpc .ui-toggle-bottom {
            opacity: 1;
            pointer-events: auto;
            transform: translateY(0);
        }

        body.ui-terminal-nonpc .ui-toggle-top {
            opacity: 0;
            pointer-events: none;
            transform: translateY(-6px);
            transition: opacity .12s ease, transform .12s ease;
        }
        body.ui-terminal-nonpc .ui-toggle-top:focus {
            opacity: 1;
            pointer-events: auto;
            transform: translateY(0);
        }
    
        /* Compact mode: collapse sticky header and hide floating widgets */
        body.compact-ui .sticky-compare .sticky-compare-btn,
        body.compact-ui .float-to-top,
        body.compact-ui .sticky-embed.embedFixed,
        body.compact-ui #pb-header,
        body.compact-ui .cto-title-text,
        body.compact-ui .nav_container.sticky,
        body.compact-ui .pb-sticky-bar-pc,
        body.compact-ui .stickyHeader,
        body.compact-ui .sticky-bar,
        body.compact-ui #contactUs,
        body.compact-ui #aiAssist,
        body.compact-ui #inside_holder,
        body.compact-ui .bottomStickyDock,
        body.compact-ui .bottom_sticky_bar,
        body.compact-ui .cto-sticky-bottom,
        body.compact-ui .pb-sticky-bar,
        body.compact-ui #lenovoSurveyWidget,
        body.compact-ui .siteAlertMessageContainer,
        body.compact-ui #custom-chat-btn,
        body.compact-ui .grecaptcha-badge {
        display: none!important;
        }
    
        /* Expanded mode: restore widgets */
        /* body:not(.compact-ui) .sticky-compare .sticky-compare-btn, */
        body:not(.compact-ui) .float-to-top,
        body:not(.compact-ui) .sticky-embed.embedFixed,
        body:not(.compact-ui) #pb-header,
        body:not(.compact-ui) .cto-title-text,
        body:not(.compact-ui) .nav_container.sticky,
        body:not(.compact-ui) .pb-sticky-bar-pc,
        body:not(.compact-ui) .stickyHeader,
        body:not(.compact-ui) .sticky-bar,
