}
}
.Pro-Store-popup-modal:not(:has(.Pro-Store-checkbox:checked)) .Pro-Store-popup-button {
  pointer-events: none;
}
.Pro-Store-popup-modal:not(:has(.Pro-Store-checkbox:checked)) .pro-Store-popup-button-text {
  pointer-events: none;
  cursor: not-allowed;
}
